}
body, div, table th, tr, td, text, button, span, label, select, input, textarea, p, li, a, ul, ol {
  font-family: "Blender","Outfit" !important; 
  
  }
body {
  font-weight:300 !important;
  font-size:12px;
  }

	.graph--heading,.data-tile--value, b, strong, div[class*="------packages-ui-Stat-Stat-module__statValue--phtGK"],.data-bit,.DataBlock_dataField__3_Oz1,h1,h2,h3,h4,h5,h6,strong,nav div,.summary div,.summary span,.data,.stat div,aside div {
    font-family:  "Blender","Outfit" !important; 
		font-weight: 600 !important;
  }
  td[class^="SortableTable"],td[class*="SortableTable-"] {
    padding: 4px;
    white-space: nowrap;
  }

	[class^="icon"], [class*=" icon"] {
    font-family: "connect-icons" !important;
  }

	
	.material-icons {
	    font-family: 'Material Icons' !important;
  }
  
  .glyphicon {
    font-family: 'Glyphicons Halflings' !important;
  }

  [class*="Gc5Card_card"] {box-shadow:0 4px 4px rgba(0, 0, 0, 0.05);border-radius:4px;border-color:#efefef;
  }
  
	/* strava Style */
.orIL6 {display:none;}
.Y4iQ6{position:relative;}
[data-testid*="device"] {position:absolute;right:-20px;color:#999 !important;display:inline-block;vertical-align:top;border:1px solid #eee;border-radius:4px;padding:2px 4px;}
[data-testid="location"] {padding-left:10px;margin-top:2px;}	



	/* ICU Style */

.activity-list {background:none !important;padding:10px !important;}
.activity-list .activity.paired-event {border-top:1px solid #e6e2f1 !important;background-color:#f2f2f2;}

[class*="DayView_dayViewColumn"] > * {border-color:#e6e6e6 !important}
.bg-grey-lighten-4 {background-color:#fffbfb !important;}
.activity.elevation-3 {background-color:#f2f2f2;border:none !important;box-shadow:none !important;border-radius:4px;}
}
